import re, os, shutil, json

work = '/private/tmp/pcd-sbx-minimax-m3.1-flash-q8w58e78/work'
src = open(os.path.join(work, 'index.html'), encoding='utf-8').read()

probe = """
<script>
window.__diag = [];
window.addEventListener('error', function(e){
  window.__diag.push('ERROR: ' + (e.message||'') + ' @' + (e.filename||'') + ':' + (e.lineno||''));
});
(function(){
  var d = document.createElement('div');
  d.id='diag';
  d.style.cssText='position:fixed;top:0;left:0;z-index:9999;color:#0f0;font:12px monospace;background:#000a;padding:8px;white-space:pre;max-width:100%;';
  document.body.appendChild(d);
  function glTest(){
    try{
      var c=document.createElement('canvas');
      var gl=c.getContext('webgl')||c.getContext('experimental-webgl');
      if(!gl) return 'NO WEBGL CONTEXT';
      var dbg=gl.getExtension('WEBGL_debug_renderer_info');
      return 'WEBGL OK | version=' + gl.getParameter(gl.VERSION) + ' | renderer=' +
             (dbg? gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER));
    }catch(err){ return 'WEBGL THREW: '+err; }
  }
  window.__diag.push('THREE loaded: ' + (typeof THREE));
  if(typeof THREE!=='undefined') window.__diag.push('THREE.REVISION: ' + THREE.REVISION);
  window.__diag.push(glTest());
  function dump(){
    var lines = window.__diag.slice();
    var st = document.getElementById('stage');
    lines.push('canvas present: ' + !!st);
    if(st){
      var gl2 = st.getContext('webgl2') || st.getContext('webgl');
      lines.push('stage ctx: ' + (gl2? 'yes':'no'));
    }
    lines.push('countdown text: "' + (document.getElementById('countdown')||{}).textContent + '" display:' +
               (document.getElementById('countdown')||{}).style.display);
    lines.push('scrubber: ' + (document.getElementById('scrubber')||{}).value);
    d.textContent = lines.join('\\n');
  }
  dump();
  setTimeout(dump, 400);
  setTimeout(dump, 1500);
  setTimeout(dump, 4000);
})();
</script>
"""

# inject probe right before </body> so it runs after the app script
out = src.replace('</body>', probe + '\n</body>')
open(os.path.join(work, '._check', 'diag.html'), 'w', encoding='utf-8').write(out)
print('wrote diag.html', len(out))

# firefox profile with software webgl forced on
prof = os.path.join(work, '._check', 'prof2')
os.makedirs(prof, exist_ok=True)
prefs = """user_pref("webgl.force-enabled", true);
user_pref("webgl.disabled", false);
user_pref("webgl.forbid-software", false);
user_pref("webgl.disable-fail-if-major-performance-caveat", true);
user_pref("webgl.out-of-process", false);
user_pref("webgl.sanity-test", false);
user_pref("gfx.webrender.all", true);
user_pref("gfx.webrender.software", true);
user_pref("layers.acceleration.disabled", true);
user_pref("browser.shell.checkDefaultBrowser", false);
user_pref("datareporting.policy.dataSubmissionEnabled", false);
user_pref("toolkit.telemetry.enabled", false);
user_pref("app.update.enabled", false);
"""
open(os.path.join(prof, 'user.js'), 'w').write(prefs)
print('wrote profile', prof)

