import re, os, sys

work = '/private/tmp/pcd-sbx-minimax-m3.1-flash-q8w58e78/work'
src = open(os.path.join(work, 'index.html'), encoding='utf-8').read()

# 1) patch renderer creation (preserveDrawingBuffer) + capture console errors,
#    injected BEFORE the app script so THREE shader errors are caught.
pre = """
<script>
window.__errs = [];
(function(){
  var ce = console.error, cw = console.warn;
  console.error = function(){ window.__errs.push('console.error: '+Array.prototype.join.call(arguments,' ')); ce.apply(console, arguments); };
  console.warn  = function(){ window.__errs.push('console.warn: '+Array.prototype.join.call(arguments,' ')); cw.apply(console, arguments); };
  window.addEventListener('error', function(e){ window.__errs.push('window.error: '+(e.message||'')+' @'+(e.lineno||'')); });
  if (typeof THREE !== 'undefined'){
    var Orig = THREE.WebGLRenderer;
    function Patched(opts){ opts = opts || {}; opts.preserveDrawingBuffer = true; return new Orig(opts); }
    Patched.prototype = Orig.prototype;
    THREE.WebGLRenderer = Patched;
  }
})();
</script>
"""

post = """
<script>
(function(){
  var TARGET = __TARGET__;
  var d = document.createElement('div');
  d.style.cssText='position:fixed;top:0;left:0;z-index:10001;color:#0f0;font:11px monospace;background:#000c;padding:6px;white-space:pre;';
  var img = document.createElement('img');
  img.style.cssText='position:fixed;top:0;left:0;width:100vw;height:100vh;z-index:10000;object-fit:cover;';
  document.body.appendChild(img);
  document.body.appendChild(d);
  function set(){
    var s = document.getElementById('scrubber');
    s.value = String(TARGET);
    s.dispatchEvent(new Event('input'));
  }
  function snap(){
    var st = document.getElementById('stage');
    try { img.src = st.toDataURL('image/png'); } catch(e){ d.textContent = 'toDataURL failed: '+e; }
    // pixel statistics of the WebGL buffer
    try {
      var gl = st.getContext('webgl', {preserveDrawingBuffer:true});
      var w = st.width, h = st.height;
      var px = new Uint8Array(w*h*4);
      gl.readPixels(0,0,w,h,gl.RGBA,gl.UNSIGNED_BYTE,px);
      var lit=0, tot=0, maxv=0;
      for(var i=0;i<px.length;i+=4){ var v=px[i]+px[i+1]+px[i+2]; tot++; if(v>24) lit++; if(v>maxv) maxv=v; }
      d.textContent = 't=' + TARGET +
        '  canvas=' + w + 'x' + h +
        '  litPx=' + (100*lit/tot).toFixed(2) + '%  maxSum=' + maxv +
        '  errs=' + (window.__errs.length ? window.__errs.join(' | ') : 'none');
    } catch(e){ d.textContent = 'readPixels failed: '+e+' errs='+window.__errs.join('|'); }
  }
  setTimeout(set, 1200);
  setTimeout(snap, 1900);
  setTimeout(snap, 2600);
})();
</script>
"""

out = src.replace('<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>',
                  '<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>\n' + pre)
out = out.replace('</body>', post.replace('__TARGET__', sys.argv[1]) + '\n</body>')
open(os.path.join(work, '._check', 'probe_t%s.html' % sys.argv[1]), 'w', encoding='utf-8').write(out)
print('wrote probe_t%s.html' % sys.argv[1])

