// Bullet tip position as a pure function of sim time.
//  0.00-1.00  free flight, constant velocity, enters from off-screen right
//  1.00-2.40  violent hydraulic drag inside the water (near-total arrest)
//  2.40-4.30  cavitation tunnel: bullet re-accelerates through the vapour
//  4.30-8.00  free flight in air again, exits frame ~t=5.22
function bulletX(t) {
  if (t < 1.0) return 5.40 - 4.7824 * t;
  if (t < 2.4) {
    var tau = t - 1.0;
    return 0.6176 - 0.12 * tau - 0.29140 * (1.0 - Math.exp(-16.0 * tau));
  }
  if (t < 4.3) {
    var t2 = t - 2.4;
    return 0.1582 - 0.40 * t2 * t2;
  }
  var u = t - 4.3, T = 0.6, v0 = 1.52, v1 = 3.0, dist;
  if (u < T) dist = v0 * u + (v1 - v0) * u * u / (2 * T);
  else dist = v0 * T + (v1 - v0) * T * 0.5 + v1 * (u - T);
  return -1.2858 - dist;
}

