    continue;
  }
  var e = Math.exp(-P.k * tau);
  var f = (1 - e) / P.k;
  var vt = -GRAV / P.k;
  pos[i * 3] = P.p[0] + P.v[0] * f;
  pos[i * 3 + 1] = P.p[1] + vt * tau + (P.v[1] - vt) * f;
  pos[i * 3 + 2] = P.p[2] + P.v[2] * f;
  var a = 1.0;
  if (tau < 0.06) a = tau / 0.06;
  var rem = P.l - tau;
  if (rem < 0.5) a *= clamp(rem / 0.5, 0, 1);
  alA[i] = a;
  szA[i] = P.s * (1.0 + 0.22 * Math.min(tau, 3.0));

