  // impact flash
  var fl = bump(t, 0.96, 1.02, 1.10, 1.38);
  flashMat.opacity = fl * 0.62;
  flash.scale.setScalar(0.10 + fl * 0.40);

  // cavitation tunnel vapour
  if (t >= 2.30 && t <= 4.70) {
    var bx = bulletX(t);
    var x1 = Math.min(bx, EXITP.x);
    var len = Math.max(0.02, IMPACT.x - x1);
    var rad = 0.085 + 0.05 * smoothstep(2.3, 3.6, t);
    tunnelMesh.visible = true;
    tunnelMesh.position.set((IMPACT.x + x1) * 0.5, bulletY(t), 0);
    tunnelMesh.scale.set(rad, len, rad);
    tunnelMat.uniforms.uTime.value = t;
    tunnelMat.uniforms.uOpacity.value = 0.70 * bump(t, 2.28, 2.55, 4.10, 4.70);
  } else {
    tunnelMesh.visible = false;
  }

  // backward cavitation wake from the entry hole
  if (t >= 2.34 && t <= 5.20) {
    var L = 0.12 + 1.55 * smoothstep(2.34, 4.60, t);
    var R = 0.035 + 0.34 * smoothstep(2.34, 4.20, t);
    wakeMesh.visible = true;
    wakeMesh.position.set(IMPACT.x + L * 0.5, bulletY(t) * 0.4, 0);
    wakeMesh.scale.set(R, L, R);
    wakeMat.uniforms.uTime.value = t;
    wakeMat.uniforms.uOpacity.value = 0.62 * bump(t, 2.32, 2.70, 4.40, 5.20);
  } else {
    wakeMesh.visible = false;
  }

  // forward conical plume
  if (t >= 3.74 && t <= 8.0) {
    var L2 = 0.18 + 2.35 * smoothstep(3.74, 5.60, t);
    var R2 = 0.045 + 0.52 * smoothstep(3.74, 5.40, t);
    plumeMesh.visible = true;
    plumeMesh.position.set(EXITP.x - L2 * 0.5, 0, 0);
    plumeMesh.scale.set(R2, L2, R2);
    plumeMat.uniforms.uTime.value = t;
    plumeMat.uniforms.uOpacity.value = 0.68 * bump(t, 3.72, 4.05, 5.60, 8.0);
  } else {
    plumeMesh.visible = false;
  }
}

