import os, sys

work = '/private/tmp/pcd-sbx-minimax-m3.1-flash-q8w58e78/work'
src = open(os.path.join(work, 'index.html'), encoding='utf-8').read()
mode = sys.argv[1]

anchor = "  /* --------------------------- scene: balloon skin ----------------------- */"
src = src.replace(anchor, "  window.__dbg = {};\n" + anchor)
src = src.replace("  var skinMesh = new THREE.Mesh(skinGeo, skinMat);",
                  "  window.__dbg.skin = skinMat; window.__dbg.core = coreMat; window.__dbg.sheet = sheetMat;\n"
                  "  var skinMesh = new THREE.Mesh(skinGeo, skinMat);")

shaders = {
    'normals': "        '  gl_FragColor = vec4(N*0.5+0.5, 1.0);',",
    'ndv':     "        '  gl_FragColor = vec4(vec3(ndv), 1.0);',",
    'spec':    "        '  gl_FragColor = vec4(spec*0.6, 1.0);',",
    'base':    "        '  gl_FragColor = vec4(base, 1.0);',",
    'alpha':   "        '  gl_FragColor = vec4(vec3(a), 1.0);',",
}
old = "        '  gl_FragColor = vec4(col, a);',"
if mode in shaders:
    src = src.replace(old, shaders[mode])

pre = """
<script>
(function(){
  if (typeof THREE !== 'undefined'){
    var Orig = THREE.WebGLRenderer;
    function Patched(o){ o=o||{}; o.preserveDrawingBuffer=true; return new Orig(o); }
    Patched.prototype = Orig.prototype; THREE.WebGLRenderer = Patched;
  }
})();
</script>
"""
src = src.replace('<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>',
                  '<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>\n' + pre)

post = """
<script>
(function(){
  var MODE = '__MODE__';
  var d = document.createElement('div');
  d.style.cssText='position:fixed;bottom:0;left:0;z-index:10001;color:#0f0;font:11px monospace;background:#000d;padding:5px;white-space:pre;';
  document.body.appendChild(d);
  function report(){
    var m = window.__dbg && window.__dbg.skin, out = [];
    if(m){
      var u = m.uniforms;
      out.push('uSpecPow=' + u.uSpecPow.value);
      out.push('uSpecGain=' + u.uSpecGain.value);
      out.push('uOpacity=' + u.uOpacity.value);
      out.push('uColor=' + u.uColor.value.r.toFixed(3) + ',' + u.uColor.value.g.toFixed(3) + ',' + u.uColor.value.b.toFixed(3));
      out.push('uDiffGain=' + u.uDiffGain.value + ' uRimGain=' + u.uRimGain.value + ' uSSS=' + u.uSSS.value);
      for(var i=0;i<4;i++){ var c=u.uLCol.value[i]; out.push('L'+i+'='+c.r.toFixed(2)+','+c.g.toFixed(2)+','+c.b.toFixed(2)); }
    } else out.push('no __dbg');
    d.textContent = out.join(' | ');
    var dt = document.createElement('div');
    dt.style.cssText='position:fixed;top:0;left:0;z-index:10001;color:#ff0;font:11px monospace;background:#000d;padding:4px;';
    dt.textContent = MODE;
    document.body.appendChild(dt);
  }
  setTimeout(function(){
    var s=document.getElementById('scrubber'); s.value='0'; s.dispatchEvent(new Event('input'));
    report();
    setTimeout(function(){
      var st = document.getElementById('stage');
      var c = document.createElement('canvas'); c.width=st.width; c.height=st.height;
      var x = c.getContext('2d');
      var g = x.createRadialGradient(c.width/2,c.height/2,0,c.width/2,c.height/2,Math.max(c.width,c.height)*0.72);
      g.addColorStop(0,'#161922'); g.addColorStop(1,'#090a0f');
      x.fillStyle=g; x.fillRect(0,0,c.width,c.height); x.drawImage(st,0,0,c.width,c.height);
      fetch('http://127.0.0.1:8765/dbg_'+MODE+'.png',{method:'POST',body:c.toDataURL('image/png')}).catch(function(){});
    }, 600);
  }, 1500);
})();
</script>
""".replace('__MODE__', mode)

src = src.replace('</body>', post + '\n</body>')
open(os.path.join(work, '._check', 'dbg_%s.html' % mode), 'w', encoding='utf-8').write(src)
print('wrote dbg_%s.html' % mode)

