src = src.replace('<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>',
                  '<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>\n' + pre)

post = """
<script>
(function(){
  function $(id){ return document.getElementById(id); }
  var L = [];
  function snap(tag){
    L.push(tag +
      ' | cd="' + $('countdown').textContent + '" disp=' + $('countdown').style.display +
      ' | scrub=' + $('scrubber').value +
      ' | pause=' + $('icon-pause').style.display + ' play=' + $('icon-play').style.display +
      ' | aria=' + $('btn-toggle').getAttribute('aria-label') +
      ' | active=' + (document.querySelector('.speed-pill.is-active')||{getAttribute:function(){return 'none'}}).getAttribute('data-speed'));
  }
  function click(id){ $(id).dispatchEvent(new MouseEvent('click', {bubbles:true})); }
  function wait(ms){ return new Promise(function(r){ setTimeout(r, ms); }); }

  (async function(){
    await wait(120);
    snap('t=0.12 (countdown running)');
    await wait(1100);
    snap('t=1.2');
    await wait(1100);
    snap('t=2.3');
    await wait(1000);
    snap('t=3.3 (should be PLAYING now)');

    // pause
    click('btn-toggle');
    await wait(60);
    snap('after pause click');
    var s1 = $('scrubber').value;
    await wait(400);
    snap('after 0.4s paused (value must be unchanged)');
    L.push('  paused value stable: ' + (s1 === $('scrubber').value));

    // scrub while paused
    var sc = $('scrubber');
    sc.value = '3.250';
    sc.dispatchEvent(new Event('input', {bubbles:true}));
    await wait(60);
    snap('after scrub to 3.250');

    // resume
    click('btn-toggle');
    await wait(300);
    snap('after resume');

    // speed pill
    var pills = document.querySelectorAll('.speed-pill');
    pills[3].dispatchEvent(new MouseEvent('click', {bubbles:true}));
    await wait(60);
    snap('after 2.0x pill');
    L.push('  aria-checks: ' + Array.prototype.map.call(pills, function(p){
      return p.getAttribute('data-speed') + '=' + p.getAttribute('aria-checked'); }).join(','));

    // re-fire
    click('btn-refire');
    await wait(60);
    snap('right after re-fire (REFIRE_HOLD, countdown hidden)');
    await wait(1200);
    snap('1.2s after re-fire (should be PLAYING)');

    // run to end
    sc.value = '7.9';
    sc.dispatchEvent(new Event('input', {bubbles:true}));
    click('btn-toggle');
    await wait(900);
    snap('after running past 8.0 (ENDED)');

    // toggle from ENDED restarts
    click('btn-toggle');
    await wait(60);
    snap('after toggle from ENDED');

    L.push('errors: ' + (window.__log.length ? window.__log.join(' | ') : 'none'));
    var d = document.createElement('div');
    d.style.cssText='position:fixed;top:0;left:0;z-index:10001;color:#0f0;font:11px monospace;background:#000e;padding:6px;white-space:pre;';
    d.textContent = L.join('\\n');
    document.body.appendChild(d);
  })();
})();
</script>
"""
src = src.replace('</body>', post + '\n</body>')
open(os.path.join(work, '._check', 'probe_state.html'), 'w', encoding='utf-8').write(src)
print('wrote probe_state.html')

