  var L = [];
  function hash(s){ var h=5381; for(var i=0;i<s.length;i++){ h=((h<<5)+h+s.charCodeAt(i))|0; } return (h>>>0)+':'+s.length; }
  function go(t){
    sc.value = String(t);
    sc.dispatchEvent(new Event('input', {bubbles:true}));
    // force a fresh frame readback
    var url = st.toDataURL('image/png');
