import re, os, sys, json, time

work = '/private/tmp/pcd-sbx-minimax-m3.1-flash-q8w58e78/work'
src = open(os.path.join(work, 'index.html'), encoding='utf-8').read()
times = sys.argv[1:] or ['0.6']
tag = str(int(time.time()))
name = 'seq_%s.html' % tag

pre = """
<script>
window.__errs = [];
(function(){
  var ce = console.error, cw = console.warn;
  console.error = function(){ window.__errs.push('E: '+Array.prototype.join.call(arguments,' ')); ce.apply(console, arguments); };
  console.warn  = function(){ window.__errs.push('W: '+Array.prototype.join.call(arguments,' ')); cw.apply(console, arguments); };
  window.addEventListener('error', function(e){ window.__errs.push('X: '+(e.message||'')+' @'+(e.lineno||'')); });
  if (typeof THREE !== 'undefined'){
    var Orig = THREE.WebGLRenderer;
    function Patched(opts){ opts = opts || {}; opts.preserveDrawingBuffer = true; return new Orig(opts); }
    Patched.prototype = Orig.prototype;
    THREE.WebGLRenderer = Patched;
  }
})();
</script>
"""

post = """
<script>
(function(){
  var TIMES = __TIMES__;
  var d = document.createElement('div');
  d.style.cssText='position:fixed;top:0;left:0;z-index:10001;color:#0f0;font:12px monospace;background:#000c;padding:6px;white-space:pre;';
  document.body.appendChild(d);
  function post_(nm, dataurl){
    return fetch('http://127.0.0.1:8765/' + nm, {method:'POST', body:dataurl})
      .then(function(){ return true; }).catch(function(e){ return false; });
  }
  function composite(stage){
    var c = document.createElement('canvas');
    c.width = stage.width; c.height = stage.height;
    var x = c.getContext('2d');
    var g = x.createRadialGradient(c.width/2, c.height/2, 0, c.width/2, c.height/2, Math.max(c.width,c.height)*0.72);
    g.addColorStop(0, '#161922'); g.addColorStop(1, '#090a0f');
    x.fillStyle = g; x.fillRect(0,0,c.width,c.height);
    x.drawImage(stage, 0, 0, c.width, c.height);
    return c.toDataURL('image/png');
  }
  function grab(i){
    if(i >= TIMES.length){
      post_('status.txt', 'data:text/plain;base64,' + btoa(encodeURIComponent(
        'errs=' + (window.__errs.length ? window.__errs.join(' | ') : 'none'))));
      return;
    }
    var t = TIMES[i];
    var s = document.getElementById('scrubber');
    s.value = String(t);
    s.dispatchEvent(new Event('input'));
    requestAnimationFrame(function(){
      requestAnimationFrame(function(){
        var st = document.getElementById('stage');
        var url;
        try { url = composite(st); } catch(e){ url = 'data:text/plain;base64,' + btoa('ERR '+e); }
        post_('comp_' + t + '.png', url).then(function(ok){
          d.textContent = 't=' + t + ' posted=' + ok + ' errs=' +
            (window.__errs.length ? window.__errs.join(' | ') : 'none');
          grab(i+1);
        });
      });
    });
  }
  setTimeout(function(){ grab(0); }, 900);
})();
</script>
"""

out = src.replace('<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>',
                  '<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>\n' + pre)
out = out.replace('</body>', post.replace('__TIMES__', json.dumps([float(x) for x in times])) + '\n</body>')
path = os.path.join(work, '._check', name)
open(path, 'w', encoding='utf-8').write(out)
open(os.path.join(work, '._check', 'last_page.txt'), 'w').write(name)
print('wrote', name)

